import datetime
import unittest

from daterange import parse_range


class TestParseRange(unittest.TestCase):
    def test_iso_date_range(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"),
            (datetime.date(2026, 10, 1), datetime.date(2026, 10, 31)),
        )

    def test_single_day_range(self):
        day = datetime.date(2026, 10, 1)
        self.assertEqual(parse_range("2026-10-01..2026-10-01"), (day, day))

    def test_reversed_date_range_is_an_error(self):
        with self.assertRaises(ValueError):
            parse_range("2026-10-31..2026-10-01")

    def test_month(self):
        self.assertEqual(
            parse_range("2026-10"),
            (datetime.date(2026, 10, 1), datetime.date(2026, 10, 31)),
        )

    def test_month_in_leap_year(self):
        self.assertEqual(
            parse_range("2024-02"),
            (datetime.date(2024, 2, 1), datetime.date(2024, 2, 29)),
        )

    def test_iso_week(self):
        self.assertEqual(
            parse_range("2026-W44"),
            (datetime.date(2026, 10, 26), datetime.date(2026, 11, 1)),
        )

    def test_iso_week_spanning_years(self):
        self.assertEqual(
            parse_range("2020-W53"),
            (datetime.date(2020, 12, 28), datetime.date(2021, 1, 3)),
        )

    def test_iso_week_53(self):
        self.assertEqual(
            parse_range("2026-W53"),
            (datetime.date(2026, 12, 28), datetime.date(2027, 1, 3)),
        )

    def test_year(self):
        self.assertEqual(
            parse_range("2026"),
            (datetime.date(2026, 1, 1), datetime.date(2026, 12, 31)),
        )

    def test_open_start_with_date(self):
        self.assertEqual(
            parse_range("..2026-10-31"),
            (None, datetime.date(2026, 10, 31)),
        )

    def test_open_end_with_date(self):
        self.assertEqual(
            parse_range("2026-10-01.."),
            (datetime.date(2026, 10, 1), None),
        )

    def test_open_start_with_month(self):
        self.assertEqual(
            parse_range("..2026-10"),
            (None, datetime.date(2026, 10, 31)),
        )

    def test_open_end_with_month(self):
        self.assertEqual(
            parse_range("2026-10.."),
            (datetime.date(2026, 10, 1), None),
        )

    def test_open_start_with_week(self):
        self.assertEqual(
            parse_range("..2026-W44"),
            (None, datetime.date(2026, 11, 1)),
        )

    def test_open_end_with_year(self):
        self.assertEqual(
            parse_range("2026.."),
            (datetime.date(2026, 1, 1), None),
        )

    def test_open_start_with_year(self):
        self.assertEqual(
            parse_range("..2026"),
            (None, datetime.date(2026, 12, 31)),
        )

    def test_spaces_around_text_and_separator(self):
        self.assertEqual(
            parse_range("  2026-10-01  ..  2026-10-31  "),
            (datetime.date(2026, 10, 1), datetime.date(2026, 10, 31)),
        )

    def test_spaces_around_single_endpoint(self):
        self.assertEqual(
            parse_range("\t2026-W44\n"),
            (datetime.date(2026, 10, 26), datetime.date(2026, 11, 1)),
        )

    def test_spaces_around_open_end(self):
        self.assertEqual(
            parse_range(" \t..  2026-12 \n"),
            (None, datetime.date(2026, 12, 31)),
        )

    def test_empty_input_is_an_error(self):
        for text in ("", "   ", "\t\n"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_double_dot_alone_is_an_error(self):
        for text in ("..", " .. ", "\t..\n"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_invalid_dates_are_errors(self):
        for text in (
            "2026-02-29",
            "2026-02-30",
            "2026-04-31",
            "2026-13-01",
            "2026-00-01",
            "2026-01-00",
            "0000-01-01",
            "2026-1-01",
            "2026-01-1",
            "26-01-01",
            "2026-01-01T00:00:00",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_invalid_months_are_errors(self):
        for text in ("2026-13", "2026-00", "2026-1", "0000-01", "2026-012"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_invalid_weeks_are_errors(self):
        for text in (
            "2026-W54",
            "2026-W00",
            "2026-W4",
            "2026-W444",
            "2026-w44",
            "0000-W01",
            "2026-W1",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_invalid_years_are_errors(self):
        for text in ("0000", "10000", "26", "20260"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_malformed_text_is_an_error(self):
        for text in (
            "not a date",
            "2026-10-01 2026-10-31",
            "2026-10-01-2026-10-31",
            "2026-10-01 to 2026-10-31",
            "2026-10-01..not-a-date",
            "not-a-date..2026-10-31",
            "2026 - 10 - 01",
            "2026-10-01...2026-10-31",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_multiple_separators_are_errors(self):
        for text in (
            "2026-10-01..2026-10-31..2026-12-31",
            "..2026-10-01..",
            "..2026..",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_reversed_period_range_is_an_error(self):
        for text in (
            "2026-11..2026-10",
            "2026-W45..2026-W44",
            "2027..2026",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)


if __name__ == "__main__":
    unittest.main()
